head.script:
scwin.trigger1_onclick = function(e) {
    grid2.setCellData(0, 0, "11111111");
};
scwin.trigger6_onclick = function(e) {
    grid2.removeAll();
    grid2.insertRow();
    grid2.insertRow();
    grid2.insertRow();
    grid2.insertRow();
    grid2.insertRow();
    //setCellInputTypeCustom="true"
    var info = {
        inputType: "text",
        options: {}
    };
    grid2.setCellInputType(0, 0, info);
    var info = {
        inputType: "calendar"
    };
    grid2.setCellInputType(1, 0, info);
    var info = {
        inputType: "select",
        itemSet: {
            label: "",
            nodeset: "",
            value: ""
        },
        options: {
            selectedData: "false",
            viewType: "icon"
        }
    };
    info.itemSet.nodeset = "response/selData/item";
    info.itemSet.label = "label";
    info.itemSet.value = "value";
    grid2.setCellInputType(2, 0, info);
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일 실행 후 'custom'버튼을 클릭한다..
    //1. Run the sample file and click the 'custom' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger6').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    // verify step 1. 왼쪽 첫번째 그리드에 별다른 값(undefined)이 보여지지 않는다.(이전에는 undefined값이 보여짐)
    //1. The first grid on the left shows no undefined values (previously undefined values are shown).
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grid2_cell_0_0').innerText == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Created By: Sang.do
    //Created By: 19-Mar-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
